import{_ as o,o as l,c as i,ae as a}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"iCost账单导入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/08-icost-bill-import-guide.md","filePath":"v1/zh/guide/08-icost-bill-import-guide.md"}'),r={name:"v1/zh/guide/08-icost-bill-import-guide.md"};function e(d,t,s,n,h,c){return l(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="icost账单导入指南" tabindex="-1">iCost账单导入指南 <a class="header-anchor" href="#icost账单导入指南" aria-label="Permalink to &quot;iCost账单导入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本指南将指导您如何从 <strong>iCost</strong> 导出账单，并导入到 <strong>考拉记账</strong> App 中。</p><p>考拉记账当前支持导入 <strong>iCost 导出的 Excel 文件</strong>（<code>.xlsx</code> / <code>.xls</code>），并且 <strong>不支持 iCost 的 CSV 文件</strong>。</p><hr><h2 id="📱-第一步-在-icost-中导出账单" tabindex="-1">📱 第一步：在 iCost 中导出账单 <a class="header-anchor" href="#📱-第一步-在-icost-中导出账单" aria-label="Permalink to &quot;📱 第一步：在 iCost 中导出账单&quot;">​</a></h2><p>不同版本的 iCost，入口可能略有差异，但思路一致：进入“导出/数据导出”，选择导出格式为 Excel 后保存文件。</p><h3 id="步骤-1-进入导出入口" tabindex="-1">步骤 1：进入导出入口 <a class="header-anchor" href="#步骤-1-进入导出入口" aria-label="Permalink to &quot;步骤 1：进入导出入口&quot;">​</a></h3><ol><li>打开 <strong>iCost</strong></li><li>进入 <strong>设置 / 更多</strong>（或“我的”页中的设置入口）</li><li>找到 <strong>导出 / 数据导出 / 导出账单</strong>（名称可能略有不同）</li></ol><h3 id="步骤-2-选择导出格式" tabindex="-1">步骤 2：选择导出格式 <a class="header-anchor" href="#步骤-2-选择导出格式" aria-label="Permalink to &quot;步骤 2：选择导出格式&quot;">​</a></h3><ol><li>选择导出格式：<strong>Excel（.xlsx / .xls）</strong></li><li>选择导出时间范围（建议每次不超过 3 个月）</li><li>导出并保存到本地（或通过“分享/保存到文件”）</li></ol><blockquote><p>⚠️ <strong>重要</strong>：导出为 CSV 会在考拉记账中提示“不支持 CSV，请使用 Excel”。</p></blockquote><hr><h2 id="📱-第二步-在考拉记账中导入" tabindex="-1">📱 第二步：在考拉记账中导入 <a class="header-anchor" href="#📱-第二步-在考拉记账中导入" aria-label="Permalink to &quot;📱 第二步：在考拉记账中导入&quot;">​</a></h2><h3 id="步骤-1-进入导入页面" tabindex="-1">步骤 1：进入导入页面 <a class="header-anchor" href="#步骤-1-进入导入页面" aria-label="Permalink to &quot;步骤 1：进入导入页面&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>“设置”</strong></li><li>在设置页面中找到 <strong>“账单导入”</strong></li><li>点击进入账单导入页面</li></ol><h3 id="步骤-2-选择导入来源" tabindex="-1">步骤 2：选择导入来源 <a class="header-anchor" href="#步骤-2-选择导入来源" aria-label="Permalink to &quot;步骤 2：选择导入来源&quot;">​</a></h3><ol><li>点击 <strong>“导入来源”</strong></li><li>在列表中选择 <strong>“iCost”</strong></li></ol><blockquote><p>⚠️ <strong>重要</strong>：必须选择“iCost”，否则系统会按其他来源解析，导致找不到表头或字段错位。</p></blockquote><h3 id="步骤-3-选择文件" tabindex="-1">步骤 3：选择文件 <a class="header-anchor" href="#步骤-3-选择文件" aria-label="Permalink to &quot;步骤 3：选择文件&quot;">​</a></h3><ol><li>点击 <strong>“文件路径”</strong></li><li>选择 iCost 导出的 <strong>Excel</strong> 文件（<code>.xlsx</code> / <code>.xls</code>）</li><li>确认文件名已显示</li></ol><h3 id="步骤-4-关联账本" tabindex="-1">步骤 4：关联账本 <a class="header-anchor" href="#步骤-4-关联账本" aria-label="Permalink to &quot;步骤 4：关联账本&quot;">​</a></h3><ol><li>点击 <strong>“关联账本”</strong></li><li>选择要导入的目标账本</li><li>确认账本选择</li></ol><h3 id="步骤-5-解析并预览" tabindex="-1">步骤 5：解析并预览 <a class="header-anchor" href="#步骤-5-解析并预览" aria-label="Permalink to &quot;步骤 5：解析并预览&quot;">​</a></h3><ol><li>点击右上角 <strong>“解析”</strong></li><li>解析成功后进入预览页</li><li>在预览页可以编辑单条记录的分类、账户、时间、金额、标签、备注等，再执行导入</li></ol><h3 id="步骤-6-导入" tabindex="-1">步骤 6：导入 <a class="header-anchor" href="#步骤-6-导入" aria-label="Permalink to &quot;步骤 6：导入&quot;">​</a></h3><ol><li>预览确认无误后点击 <strong>“导入”</strong></li><li>等待导入完成</li></ol><hr><h2 id="📋-icost账单文件格式说明-excel" tabindex="-1">📋 iCost账单文件格式说明（Excel） <a class="header-anchor" href="#📋-icost账单文件格式说明-excel" aria-label="Permalink to &quot;📋 iCost账单文件格式说明（Excel）&quot;">​</a></h2><p>考拉记账对 iCost Excel 的校验点：</p><ul><li>Excel 需要存在可读取的工作表</li><li>表头行需要包含 <strong>“日期”</strong> 字样（用于定位表头行）</li></ul><blockquote><p>📝 <strong>提示</strong>：如果 iCost 导出支持选择语言，建议导出为中文表头（至少保证表头行包含“日期”）。</p></blockquote><h3 id="读取字段-按列位置" tabindex="-1">读取字段（按列位置） <a class="header-anchor" href="#读取字段-按列位置" aria-label="Permalink to &quot;读取字段（按列位置）&quot;">​</a></h3><p>考拉记账按列位置读取 iCost Excel 的部分字段，其它列会被忽略：</p><table tabindex="0"><thead><tr><th>列序号</th><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>日期</td><td>支持 <code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code> / <code>yyyy-MM-ddTHH:mm:ss</code> / <code>yyyy-MM-dd HH:mm:ss</code>；也支持 Excel 序列号日期</td></tr><tr><td>2</td><td>类型</td><td>文本需包含“支出”或“收入”关键字；包含“支出”=支出，包含“收入”=收入</td></tr><tr><td>3</td><td>金额</td><td>允许带 <code>+</code>/<code>-</code>，导入会自动去除符号并去掉千分位逗号</td></tr><tr><td>4</td><td>父分类</td><td>用于匹配考拉记账收支项目父类名称</td></tr><tr><td>5</td><td>子分类</td><td>为空时会自动使用“父分类”的值</td></tr><tr><td>6</td><td>账户</td><td>为空时会使用默认账户（数据库 id=1）作为兜底</td></tr><tr><td>8</td><td>备注</td><td>备注文本</td></tr><tr><td>9</td><td>币种代码</td><td>例如 <code>CNY</code> / <code>USD</code>；为空或匹配失败时使用目标账本的默认币种</td></tr><tr><td>10</td><td>标签</td><td>多个标签用逗号分隔（同时支持中文逗号 <code>，</code>）</td></tr></tbody></table><h3 id="导入映射-考拉记账" tabindex="-1">导入映射（考拉记账） <a class="header-anchor" href="#导入映射-考拉记账" aria-label="Permalink to &quot;导入映射（考拉记账）&quot;">​</a></h3><ul><li>日期（row[0]）→ 账单日期</li><li>类型（row[1]，含“支出/收入”）→ 账单类型</li><li>金额（row[2]）→ 金额</li><li>一级分类（row[3]）→ 一级分类（并匹配/创建 parentCategoryId 等）</li><li>二级分类（row[4]，空则用一级）→ 二级分类 （并匹配/创建 childCategoryId 等）</li><li>账户（row[5]，空则默认账户）→账户名称</li><li>第7列（row[6]）→ 不入库（未使用）</li><li>备注（row[7]）→ 备注</li><li>货币代码（row[8]）→ 货币名称</li><li>标签（row[9]）→ 标签（解析/创建标签后入库）</li></ul><hr><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><ol><li><strong>仅支持 Excel</strong>：iCost CSV 文件无法导入。</li><li><strong>不自动去重</strong>：重复导入同一份文件会生成重复账单记录，请避免多次导入同一时间段。</li><li><strong>表头语言</strong>：解析依赖表头行包含“日期”；若导出为非中文表头，可能导致找不到表头而解析失败。</li><li><strong>账户为空的处理</strong>：若 iCost 导出中“账户”列为空，会使用默认账户（id=1）兜底；建议导出时尽量补全账户信息，或在预览页统一修改。</li><li><strong>收支项目匹配</strong>：按“父分类 + 子分类”名称匹配；匹配失败会在预览页提示不完善，需要手动选择正确的收支项目后再导入。</li></ol><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-提示-未找到-icost-账单表头" tabindex="-1">Q1：提示“未找到 iCost 账单表头”？ <a class="header-anchor" href="#q1-提示-未找到-icost-账单表头" aria-label="Permalink to &quot;Q1：提示“未找到 iCost 账单表头”？&quot;">​</a></h3><p><strong>A：</strong> 通常是以下原因：</p><ol><li>Excel 中表头行不包含“日期”字样（例如导出为英文表头）</li><li>文件不是 iCost 导出的账单文件，或表结构被二次编辑破坏</li><li>Excel 文件为空/没有工作表</li></ol><p>建议重新从 iCost 导出，并优先选择中文表头的导出方式。</p><h3 id="q2-账户为空导致导入后都进了同一个账户" tabindex="-1">Q2：账户为空导致导入后都进了同一个账户？ <a class="header-anchor" href="#q2-账户为空导致导入后都进了同一个账户" aria-label="Permalink to &quot;Q2：账户为空导致导入后都进了同一个账户？&quot;">​</a></h3><p><strong>A：</strong> 这是正常兜底行为：当“账户”列为空时，会使用默认账户（id=1）。可在预览页批量编辑账户，或在 iCost 导出前补全账户字段后再重新导入。</p><h3 id="q3-分类匹配不上怎么办" tabindex="-1">Q3：分类匹配不上怎么办？ <a class="header-anchor" href="#q3-分类匹配不上怎么办" aria-label="Permalink to &quot;Q3：分类匹配不上怎么办？&quot;">​</a></h3><p><strong>A：</strong> 在导入预览页点进单条记录手动选择收支项目；或者先在考拉记账里创建好与 iCost 导出文件同名的收支项目后再重新解析。</p><hr><h2 id="📚-相关教程" tabindex="-1">📚 相关教程 <a class="header-anchor" href="#📚-相关教程" aria-label="Permalink to &quot;📚 相关教程&quot;">​</a></h2><ul><li><a href="./01-template-bill-import-guide">模板账单导入指南</a></li><li><a href="./02-wechat-bill-import-guide">微信账单导入教程</a></li><li><a href="./03-alipay-bill-import-guide">支付宝账单导入教程</a></li><li><a href="./07-pixiu-bill-import-guide">貔貅账单导入指南</a></li><li><a href="./04-multi-ledger-guide">多账本功能说明</a></li></ul><hr><p><strong>最后更新</strong>：2026年4月</p>',55)])])}const b=o(r,[["render",e]]);export{u as __pageData,b as default};
